def header(active):
 links=''.join(f'<a href="{name}"'+(' aria-current="page"' if name==active else '')+f'>{label}</a>' for name,label in [('index.html','Főoldal'),('kezelesek.html','Kezelések'),('rolunk.html','Rólunk'),('kapcsolat.html','Kapcsolat')])
 target='#kapcsolat' if active in ['index.html','kezelesek.html','rolunk.html','kapcsolat.html'] else 'kapcsolat.html#kapcsolat'
 return '<a class="skip" href="#tartalom">Ugrás a tartalomra</a><header class="header"><div class="wrap header-inner"><a href="index.html" aria-label="Eliza Beauty Salon, főoldal"><img class="logo" src="logo/logo.svg" alt="Eliza Beauty Salon" width="120" height="74"></a><button class="menu-btn" aria-expanded="false" aria-controls="menu" type="button">Menü</button><nav class="nav" id="menu" aria-label="Fő navigáció">'+links+f'<a class="btn" href="{target}">Időpontot kérek</a></nav></div></header>'
def hero(label,title,description,slug):
 return f'<section class="page-hero wrap"><nav class="breadcrumbs" aria-label="Morzsamenü"><a href="index.html">Főoldal</a> / <span>{label}</span></nav><div class="page-hero-grid"><div><div class="kicker">{label}</div><h1>{title}</h1><p>{description}</p><div class="actions"><a class="btn" href="#kapcsolat">Időpontot kérek</a></div></div><figure>{photo(slug,True)}</figure></div></section>'
def page(filename,title,description,main):
 main=re.sub(r'<nav class="breadcrumbs"[^>]*>.*?</nav>','',main,flags=re.S)
 form_name='idopontkeres-'+filename.replace('.html','')
 old='<form data-demo="contact">'
 replacement='<form name="'+form_name+'" method="POST" action="/koszonjuk.html" data-netlify="true" netlify-honeypot="bot-field" data-contact-form><input type="hidden" name="form-name" value="'+form_name+'"><p hidden><label>Hagyd üresen ezt a mezőt: <input name="bot-field" tabindex="-1" autocomplete="off"></label></p>'
 main=main.replace(old,replacement)
 main=main.replace('Bemutató űrlap, nem küld üzenetet. Éles működéskor Eliza e-mailben vagy telefonon egyezteti vissza az időpontot.','Az üzenet elküldése után e-mailben egyeztetjük a részleteket. Az időpontkérés nem jelent automatikus foglalást.')

 url=domain+('' if filename=='index.html' else filename)
 faq_items=[]
 for q,a in re.findall(r'<details><summary>(.*?)</summary><p>(.*?)</p></details>',main,re.S):
  text=lambda x:unescape(re.sub('<[^>]+>','',x)).strip()
  faq_items.append({'@type':'Question','name':text(q),'acceptedAnswer':{'@type':'Answer','text':text(a)}})
 schema=[{'@context':'https://schema.org','@type':'WebPage','url':url,'name':title,'description':description,'inLanguage':'hu-HU','about':{'@type':'BeautySalon','name':'Eliza Beauty Salon'}}]
 if faq_items:schema.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':faq_items})
 head=f'''<!doctype html><html lang="hu"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{url}"><link rel="icon" href="logo/favicon.svg"><link rel="preload" href="assets/fonts/cormorant-garamond-latin-v1.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/jost-latin-v1.woff2" as="font" type="font/woff2" crossorigin><link href="{css_name}" rel="stylesheet"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}"><meta property="og:type" content="website"><meta property="og:locale" content="hu_HU"><meta property="og:site_name" content="Eliza Beauty Salon"><meta property="og:image" content="{domain}images/website/social-preview.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Kozmetikai arckezelés"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(description)}"><meta name="twitter:image" content="{domain}images/website/social-preview.jpg"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body>'''
 html=head+header(filename)+'<main id="tartalom">'+main+'</main>'+footer+f'<script src="{js_name}" defer></script></body></html>'
 primary=re.search(r'<img[^>]*fetchpriority="high"[^>]*>',main)
 if primary:
  tag=primary[0];attrs=dict(re.findall(r'([\w-]+)="([^"]*)"',tag))
  preload='<link rel="preload" as="image" href="'+attrs['src']+'" fetchpriority="high"'
  if 'srcset' in attrs:preload+=' imagesrcset="'+attrs['srcset']+'" imagesizes="'+attrs.get('sizes','100vw')+'"'
  html=html.replace('</head>',preload+'></head>',1)
 (root/filename).write_text(html,encoding='utf-8')

